import{g as a,ae as r,r as t,B as o}from"./chunks/framework.CZ-ntRvv.js";const f=JSON.parse('{"title":"v1 Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"docs/changelog/v1.md","filePath":"docs/changelog/v1.md","lastUpdated":1791747207000}'),n={name:"docs/changelog/v1.md"};function i(l,e,s,h,p,d){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="v1-changelog" tabindex="-1">v1 Changelog <a class="header-anchor" href="#v1-changelog" aria-label="Permalink to “v1 Changelog”">​</a></h1><p>Every frappe-ui 1.x release, newest first. Each entry names its kind in parentheses (fix, additive or deprecation) and links to its pull request. To upgrade from v0, see <a href="/docs/changelog/v0-to-v1">Changes from v0 to v1</a> and the <a href="/docs/migration">migration guide</a>.</p><h2 id="_1-0-1" tabindex="-1">1.0.1 <a class="header-anchor" href="#_1-0-1" aria-label="Permalink to “1.0.1”">​</a></h2><h3 id="patch-changes" tabindex="-1">Patch Changes <a class="header-anchor" href="#patch-changes" aria-label="Permalink to “Patch Changes”">​</a></h3><ul><li>Charts: a category axis label that is shortened in the middle now keeps its ending, and no longer gets a second ellipsis at the end (fix). <a href="https://github.com/frappe/frappe-ui/pull/1279" target="_blank" rel="noreferrer">#1279</a></li><li>Checkbox: a checked or indeterminate checkbox now lightens on hover and press, and checkboxes no longer show a shadow on hover (fix). <a href="https://github.com/frappe/frappe-ui/pull/1186" target="_blank" rel="noreferrer">#1186</a></li><li>Editor: images and videos without a size get one only after the person&#39;s own edit, not when a document opens or a collaborator edits it, and one Ctrl+Z now undoes the person&#39;s edit (fix). <a href="https://github.com/frappe/frappe-ui/pull/1266" target="_blank" rel="noreferrer">#1266</a></li><li>PageHeaderMobile: the <code>#prefix</code> and <code>#suffix</code> slots now follow the text direction, so in right-to-left pages the back button sits on the right (fix). <a href="https://github.com/frappe/frappe-ui/pull/1230" target="_blank" rel="noreferrer">#1230</a></li><li>Progress: a bar without a <code>label</code> now has the accessible name &quot;Progress&quot; instead of its percentage, so screen readers do not read the value twice (fix). <a href="https://github.com/frappe/frappe-ui/pull/1113" target="_blank" rel="noreferrer">#1113</a></li><li>SidebarRailItem: a <code>subtle</code> item paints no fill behind an image, so a rounded logo shows no gray rim at its corners (fix). <a href="https://github.com/frappe/frappe-ui/pull/1272" target="_blank" rel="noreferrer">#1272</a></li><li>Editor: dragging a link or selected text out of a read-only editor now carries the browser&#39;s URL or text, as it does from plain HTML (fix). <a href="https://github.com/frappe/frappe-ui/pull/1104" target="_blank" rel="noreferrer">#1104</a></li><li>Realtime: updates keep arriving after a reconnect and on a new socket (fix). <a href="https://github.com/frappe/frappe-ui/pull/1105" target="_blank" rel="noreferrer">#1105</a></li><li>Editor: the mention, emoji, tag and slash-command menus stay next to the caret when the page or the editor&#39;s scroll container scrolls or the window resizes, and never show a position meant for an older list (fix). <a href="https://github.com/frappe/frappe-ui/pull/1161" target="_blank" rel="noreferrer">#1161</a></li></ul>',5)])])}const g=a(n,[["render",i]]);export{f as __pageData,g as default};
